mapper.select:
SELECT o.NOTE FROM orders o
 WHERE o.CUSTOMER_NAME = #{customerName,jdbcType=varchar}
   AND o.ORDER_ID = #{orderId, jdbctype=NUMERIC}
   AND o.STATUS = #{status,mode=OUTPUT}

SELECT o.NOTE FROM orders o
 WHERE o.CUSTOMER_NAME = #{customerName,jdbcType=VARCHAR}
   AND o.ORDER_ID = #{orderId:NUMERIC}
   AND o.AMOUNT = #{amount,jdbcType=DECIMAL,numericScale=2}
